# --- your code ---
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.items = OrderedDict()       # least recently used first

    def get(self, key: int) -> int:
        if key not in self.items:
            return -1
        self.items.move_to_end(key)      # a read is a use
        return self.items[key]

    def put(self, key: int, value: int) -> None:
        self.items[key] = value
        self.items.move_to_end(key)
        if len(self.items) > self.capacity:
            self.items.popitem(last=False)   # evict the least recently used


# --- provided: do not edit ---
def run_cache(capacity: int, ops: list[list]) -> list:
    cache = LRUCache(capacity)
    return [getattr(cache, name)(*args) for name, *args in ops]
